import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"挑战与奖励","description":"","frontmatter":{},"headers":[],"relativePath":"modules/dungeon/challenges.md","filePath":"modules/dungeon/challenges.md","lastUpdated":0}`),a={name:`modules/dungeon/challenges.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="挑战与奖励" tabindex="-1">挑战与奖励 <a class="header-anchor" href="#挑战与奖励" aria-label="Permalink to “挑战与奖励”">​</a></h1><p>玩家侧的完整循环包括怎么进入副本, 次数怎么算, 奖励怎么发, 以及失败时会发生什么</p><h2 id="进入流程" tabindex="-1">进入流程 <a class="header-anchor" href="#进入流程" aria-label="Permalink to “进入流程”">​</a></h2><ol><li><strong>发起</strong>: 你先用 <code>/edg list</code> 查看可用副本, 再用 <code>/edg enter &lt;副本ID&gt;</code> 发起挑战 (组队时<strong>仅队长可发起</strong>)</li><li><strong>前置判定</strong>: 插件依次检查副本是否存在, 进入权限 (<code>emakidungeon.dungeon.&lt;副本ID&gt;</code>), 队伍状态, 满载与限制 (冷却 → 日 → 周 → 月 → 时段), 任一不过会立即提示原因</li><li><strong>选难度</strong>: 屏幕弹出&quot;选择难度&quot;面板, 你从副本 <code>difficulty</code> 配置的档位中选一个</li><li><strong>选掉落分配模式</strong>: 弹出&quot;选择掉落分配模式&quot;面板, 可选项来自 <code>drop.mode-allowed</code></li><li><strong>准备确认</strong>: 在 <code>enter.prepare-window-seconds</code> 秒内, 全员用 <code>/edg ready</code> 或点击确认按钮就绪, 超时则挑战作废</li><li><strong>世界准备等待</strong>: 插件克隆副本模板世界, 并按 <code>enter.wait-channel</code> 显示等待提示 (bossbar / 计分板 / 聊天); 任一队员可 <code>/edg cancel</code> 取消, 等待超过 <code>enter.wait-timeout-seconds</code> 自动作废</li><li><strong>进入</strong>: 分配到池中的世界, 传送入场, <strong>计入当日次数</strong>, 进入瞬间有快照用于日后回滚</li></ol><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>发起挑战时要求全体队员在线, 任一队员离线都会被拒绝; 同一队伍同时只能有一个进行中的挑战</p></div><h2 id="次数限制" tabindex="-1">次数限制 <a class="header-anchor" href="#次数限制" aria-label="Permalink to “次数限制”">​</a></h2><p>每个副本的 <code>limits</code> 段独立计算, 判定顺序固定为 <strong>月 &gt; 周 &gt; 日</strong>:</p><ul><li><code>count</code> 为 <code>0</code> 表示该层不限; 任何一层不满足 (次数耗尽或不在允许的周几/月周次/时段内) 都会拒绝进入, 并提示距离下次可挑战还有多久</li><li><code>cooldown-seconds</code> 是两次进入之间的硬冷却, 它单独判定</li><li>计数按天分桶, 时区取 <code>general.timezone</code>, 留空就用服务器时区</li><li>你用 <code>/edg stats [玩家] [副本ID]</code> 查看自己的 日/周/月 已用次数, 冷却与最佳成绩</li><li>OP 或拿到 <code>emakidungeon.bypass.limit</code> 的玩家绕过全部次数与冷却</li></ul><h2 id="队伍规则" tabindex="-1">队伍规则 <a class="header-anchor" href="#队伍规则" aria-label="Permalink to “队伍规则”">​</a></h2><ul><li>队伍人数上限 <code>party.max-size</code>, 邀请模式 <code>party.invite-mode</code> (<code>public</code> 直接进 / <code>apply</code> 申请待批 / <code>invite</code> 仅邀请)</li><li><strong>只有队长</strong>能发起挑战, 选择难度与分配模式; 有队员离线时不允许发起</li><li>队伍正在挑战中时不再接纳新成员, 也不会开始第二场挑战</li><li>队伍频道 (<code>/edg party chat</code>) 开启后你的消息只有队友可见; 副本内世界消息默认实例内闭环, 你用 <code>/edg globalchat on</code> 可切回全服互通</li></ul><p>命令与权限细节见 <a href="./commands.html#队伍子命令">命令与权限</a></p><h2 id="局内奖励与结算" tabindex="-1">局内奖励与结算 <a class="header-anchor" href="#局内奖励与结算" aria-label="Permalink to “局内奖励与结算”">​</a></h2><ul><li><strong>局内奖励分两条路</strong>: 走分配的掉落 (ROLL / 贡献池 / 平分) 和流程发放的物品会<strong>先进你的暂存区</strong>, 并提示&quot;已暂存本局, 通关后发放&quot;; 副本里的奖励箱在结算前<strong>锁定不可拾取</strong></li><li><strong>通关才结算</strong>: 通关时插件把暂存区的奖励发放, 再按 <code>settlement.commands</code> 逐条执行结算命令 (可调 EmakiItem/EmakiLevel 发物品与经验)</li><li>五种分配模式 (<code>drop.default-mode</code> / <code>drop.mode-allowed</code>), 决定怪物掉落怎么处理: <ul><li><code>free</code> 保持原版掉落: 不拦截, 谁捡归谁 (默认)</li><li><code>roll</code> 掉落自动 ROLL, 赢家那份记入其暂存区, 通关发放</li><li><code>killer</code> 掉落归击杀者</li><li><code>score</code> 掉落进入贡献池, 结算按评分贡献加权分配 (<code>drop.levels</code> 的等级权重参与)</li><li><code>share</code> 掉落全队平分</li></ul></li><li>发放时统一提示&quot;本局暂存奖励已发放 (N 件)&quot;; 开了奖励箱的走奖励箱, 没开的直接进背包</li><li>打怪掉落的倍率按 <code>difficulty.&lt;档名&gt;.drop-multiplier</code> 结算; 波次配置了禁止掉落的怪物不产出</li></ul><h2 id="奖励箱与领取" tabindex="-1">奖励箱与领取 <a class="header-anchor" href="#奖励箱与领取" aria-label="Permalink to “奖励箱与领取”">​</a></h2><p><code>rewardbox.enabled: true</code> (默认) 时, 通关奖励会进入<strong>个人奖励箱</strong>, 通关后聊天栏会给出 <code>/edg rewards</code> 的可点击提示:</p><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td><code>/edg rewards</code></td><td>打开奖励箱界面, 拖拽物品到背包即可领取</td></tr><tr><td>点击&quot;上一页 / 下一页&quot;</td><td>翻页; 基础页数见 <code>gui/rewardbox.yml</code> 的 <code>default-pages</code></td></tr><tr><td>点击&quot;自动流入&quot;</td><td>开启后之后的奖励直接进背包 (背包满时仍留奖励箱); 关闭则继续存奖励箱手动领</td></tr></tbody></table><p>容量规则 (容量键是 <code>gui/rewardbox.yml</code> 的 <code>capacity-slots</code>, 默认 135 格):</p><ul><li>奖励箱<strong>满了拒绝领取</strong>, 物品留在箱里等你腾出位置</li><li>ROLL 分配时<strong>跳过已满箱的玩家</strong></li><li>所有人都满箱时, 这批奖励直接<strong>落地为可拾取物</strong></li><li><code>rewardbox.enabled: false</code> 时整个功能关闭: 通关奖励直接进背包, 背包满则落地为可拾取掉落物</li></ul><h2 id="失败-退出与回滚" tabindex="-1">失败, 退出与回滚 <a class="header-anchor" href="#失败-退出与回滚" aria-label="Permalink to “失败, 退出与回滚”">​</a></h2><table tabindex="0"><thead><tr><th>情形</th><th>结果</th></tr></thead><tbody><tr><td>主动退出 (<code>/edg leave</code>)</td><td>聊天输入 <code>确认</code> 二次确认后退出; 按进入前快照回滚背包与状态, 送回原位置; <strong>本局暂存奖励全部作废</strong></td></tr><tr><td>挑战失败 / 全员死亡 / 超时销毁</td><td>同样全部作废: 暂存的物品, 经验等产出一笔勾销, 玩家按快照还原并送回进入前位置</td></tr><tr><td>断线重连</td><td>重连成功自动回到进行中的实例; 实例已结束则按快照恢复并提示</td></tr><tr><td>插件异常导致实例消失</td><td>孤儿快照自动还原 (背包与状态按进入前快照恢复)</td></tr></tbody></table><p>一句话总结: <strong>只有通关才能拿到东西</strong>, 中途离场的沉没成本只有本局投入</p><h2 id="观战与局内生存" tabindex="-1">观战与局内生存 <a class="header-anchor" href="#观战与局内生存" aria-label="Permalink to “观战与局内生存”">​</a></h2><ul><li>你死亡时按 <code>difficulty.&lt;档名&gt;.respawn-count</code> 消耗重生次数, 每次阵亡会广播剩余次数</li><li>重生次数用尽后转入<strong>观战模式</strong>; 观战玩家只能转动视角, <strong>不能自由飞行</strong>, 离开副本自动解锁</li><li>你跑到副本边界外时会被自动拉回出生点 (<code>guard.boundary_pullback</code>)</li><li>流程里可以配置 <code>temp_items</code> 临时物品: 背包满时发不下去会提示, 实例结束自动收回</li></ul><h2 id="评分与排行榜" tabindex="-1">评分与排行榜 <a class="header-anchor" href="#评分与排行榜" aria-label="Permalink to “评分与排行榜”">​</a></h2><ul><li>本局评分由 <code>score</code> 五项权重 (伤害, 击杀, 治疗, 死亡, 承伤) 计算, 上限 <code>score.max</code></li><li>你用 <code>/edg rank &lt;副本ID&gt;</code> 查看该副本前 10 名 (分数, 用时, 难度, 队伍); 保留条数由 <code>leaderboard.max-entries</code> 控制</li><li>结算与超时的倒计时提醒按 <code>timer.messages</code> 的档位推送</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};